#!/usr/bin/env python3
"""Builds public/ect.html: the ECT (Emotional Breakthrough) landing page as its own public page, straight from the app's
ECT view (template t-ect + its code + the small renderer). Run by tools/build.py, so the two always stay the same."""
import os, re
root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
s = open(os.path.join(root, 'public/index.html'), encoding='utf-8').read()
a = s.index('<template id="t-ect">'); b = s.index('</template>', a) + len('</template>')
tpl = s[a:b]
tpl = tpl.replace('<a class="ghost solid" href="OneOnOne.dc.html" target="_self">', '<a class="ghost solid" href="https://colourmeneurospicy.com.au/pages/work-with-sav" target="_self">').replace('Back to my dashboard</a>', 'All the ways to work with Sav</a>')
tpl = tpl.replace('1:1 Breakthrough · Your next step', 'Colour Me Neurospicy · 1:1 with Sav')
tpl = re.sub(r'<sc-if value="\{\{noEctVideo\}\}"[^>]*>.*?</sc-if>', '', tpl, count=1, flags=re.S)
helm = re.search(r'<helmet>(.*?)</helmet>', tpl, re.S).group(1)
r0 = s.index('var WHOLE = '); r1 = s.index('var VIEWS = {};')
runtime = s[r0:r1]
v0 = s.index('VIEWS["ECT.dc.html"] = '); v1 = s.index('})() };', v0) + len('})() };')
view = s[v0:v1]
view = view.replace("I’m one of your 1:1 Breakthrough clients and I’d love to know more", "I’d love to know more").replace("+ ' (1:1 client)'", "")
view = view.replace('"enquiryEmail": "savannah@savannahdenny.com.au"', '"enquiryEmail": "savannah@colourmeneurospicy.com.au"')
page = ('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">'
        '<title>The Emotional Breakthrough · ECT with Sav</title><meta name="description" content="Release years of stored anger, sadness, fear, hurt, guilt, shame and grief at the root. Six 1:1 sessions of ECT with Sav.">'
        '<meta name="theme-color" content="#4E0C08"><link rel="icon" href="/icons/favicon-32.png" sizes="32x32">' + helm + '</head><body>'
        '<!-- GENERATED by tools/build_ect.py from the ECT view in public/index.html. Edit the app view, not this file. -->'
        + tpl + '<div id="app"></div><script>\n' + runtime + 'var VIEWS = {};\n' + view +
        '\n(function () { var v = VIEWS["ECT.dc.html"], root = document.createElement("div"); root.id = "v-ect"; document.getElementById("app").appendChild(root);'
        ' var inst = new v.cls(v.props); inst._root = root; inst._tpl = Array.prototype.slice.call(document.getElementById("t-ect").content.childNodes); inst._render(); if (inst.componentDidMount) inst.componentDidMount(); })();\n'
        '/* came here from a tool in the app (like the Emotional Blueprint)? give them a way back */\n'
        '(function () { try { var r = document.referrer; if (!r || r.indexOf(location.origin) !== 0 || history.length < 2) return; var hd = document.querySelector("#v-ect header"); if (!hd) return; var b = document.createElement("button"); b.type = "button"; b.className = "ghost solid"; b.textContent = "\u2190 Back"; b.onclick = function () { history.back(); }; hd.insertBefore(b, hd.firstChild); } catch (e) {} })();\n</script></body></html>')
open(os.path.join(root, 'public/ect.html'), 'w', encoding='utf-8').write(page)
print('built public/ect.html', round(len(page) / 1e6, 2), 'MB')
